// Pretend backend. Do not edit this file.
//
// - Every request takes ~400ms.
// - The server keeps its OWN session (separate from what the UI stores) and
//   enforces roles on every request, like a real backend would.
import type { BaseQueryFn } from '@reduxjs/toolkit/query';
import { db } from './mockData';
import type { ApplicationStatus, Role, User } from '../types';

export interface FakeArgs {
  method: 'GET' | 'POST' | 'PATCH' | 'DELETE';
  url: string;
  body?: unknown;
}

export interface ApiError {
  status: number;
  message: string;
}

const SESSION_KEY = 'cusb_fake_session';

const ACCOUNTS: Record<Role, User> = {
  admin: { id: 1, name: 'Ali Admin', role: 'admin' },
  hr: { id: 2, name: 'Hala HR', role: 'hr' },
  member: { id: 3, name: 'Mona Member', role: 'member' },
};

const delay = (ms = 400) => new Promise((resolve) => setTimeout(resolve, ms));
const getSessionRole = () => localStorage.getItem(SESSION_KEY) as Role | null;
const fail = (status: number, message: string) => ({ error: { status, message } as ApiError });

export const fakeBaseQuery: BaseQueryFn<FakeArgs, unknown, ApiError> = async ({ method, url, body }) => {
  await delay();
  const role = getSessionRole();

  // ---- auth
  if (method === 'POST' && url === '/login') {
    const requested = (body as { role: Role }).role;
    localStorage.setItem(SESSION_KEY, requested);
    return { data: ACCOUNTS[requested] };
  }
  if (method === 'POST' && url === '/logout') {
    localStorage.removeItem(SESSION_KEY);
    return { data: { ok: true } };
  }

  // ---- events (public read, admin delete)
  if (method === 'GET' && url === '/events') {
    return { data: structuredClone(db.events) };
  }
  const eventMatch = url.match(/^\/events\/(\d+)$/);
  if (eventMatch) {
    const id = Number(eventMatch[1]);
    const event = db.events.find((e) => e.id === id);
    if (method === 'GET') {
      return event ? { data: structuredClone(event) } : fail(404, 'Event not found.');
    }
    if (method === 'DELETE') {
      if (role !== 'admin') return fail(403, 'Only admins can delete events.');
      if (!event) return fail(404, 'Event not found.');
      db.events = db.events.filter((e) => e.id !== id);
      return { data: { id } };
    }
  }

  // ---- applications (HR only)
  if (url.startsWith('/applications')) {
    if (role !== 'hr') return fail(403, 'Only HR can access applications.');

    if (method === 'GET' && url === '/applications') {
      return { data: structuredClone(db.applications) };
    }
    const appMatch = url.match(/^\/applications\/(\d+)$/);
    if (appMatch && method === 'PATCH') {
      const id = Number(appMatch[1]);
      const current = db.applications.find((a) => a.id === id);
      if (!current) return fail(404, 'Application not found.');
      const { status } = body as { status: ApplicationStatus };
      if (current.status === 'accepted' && status !== 'accepted') {
        return fail(409, 'An accepted application cannot be changed.');
      }
      db.applications = db.applications.map((a) => (a.id === id ? { ...a, status } : a));
      return { data: structuredClone(db.applications.find((a) => a.id === id)) };
    }
  }

  return fail(404, `No route for ${method} ${url}`);
};
